class Solution {public:int solve(int n,vector<vector<int>> edges){vector<vector<int>>adj(n);for(auto e:edges){adj[e[0]].push_back(e[1]);adj[e[1]].push_back(e[0]);}vector<bool>seen(n);int answer=0;for(int s=0;s<n;s++)if(!seen[s]){answer++;queue<int>q;q.push(s);seen[s]=true;while(!q.empty()){int u=q.front();q.pop();for(int v:adj[u])if(!seen[v]){seen[v]=true;q.push(v);}}}return answer;}};